#!/usr/bin/env bash
# Section 5.6 MATCHED all-baseline arm.
#
# WHY THIS IS NEEDED. The arm plotted as "homog" in the 5.6 figure is
# runs/chapter5_v2/s531_b2, generated by run_mesh_sampled.py, which does NOT
# pass apply_colour_filter and so inherits the runner default True. Every
# heterogeneous run passes apply_colour_filter=False. That is a second
# confound on top of the all-baseline checkpoint one, and it is large.
# This arm is generated by the SAME script as the heterogeneous runs, so the
# colour filter, checkpoint handling, wearable seeding and lam all match.
set -u
LOGS=logs/homog_baseline_$(date +%Y%m%d_%H%M%S)
mkdir -p "$LOGS"; echo "$$" > "$LOGS/batch.pid"
echo "logs -> $LOGS (wrapper pid $$)"
.venv/Scripts/python.exe -u experiments/stage6_spatial_mesh/run_heterogeneous_comparator.py \
    --mode nig_product --homogeneous --homog-variant baseline \
    --seeds 42,1042,2042,3042,4042 --root runs/chapter5_v2/s5_6_homog_baseline \
    >> "$LOGS/homog_baseline.log" 2>&1
echo "exit=$? -- DONE"
